  position: relative;
}
.bcn-fd-tl__row[hidden],
.bcn-fd-tl__group[hidden] {
  display: none;
}
.bcn-fd-tl__row:hover .bcn-fd-tl__track {
  background: color-mix(in srgb, var(--color-background-default) 70%, transparent);
}
.bcn-fd-tl__label {
  z-index: 3;
  padding: 0 var(--spacing-300);
  background: var(--color-background-elevation-raised);
  border-right: 1px solid var(--color-border-default);
  font-weight: var(--typography-font-weight-semibold);
  white-space: nowrap;
  align-items: center;
  display: flex;
  position: sticky;
  left: 0;
}
.bcn-fd-tl__label a {
  color: var(--color-content-default);
  text-decoration: none;
}
.bcn-fd-tl__label a:hover,
.bcn-fd-tl__label a:focus-visible {
  text-decoration: underline;
}
.bcn-fd-tl__row--campaign {
  border-bottom: 1px solid var(--color-border-default);
}
.bcn-fd-tl__row--campaign .bcn-fd-tl__label {
  font-weight: var(--typography-font-weight-medium);
  color: var(--color-content-default-secondary);
}
.bcn-fd-tl__track {
  position: relative;
}
.bcn-fd-tl__batch {
  z-index: 3;
  background: var(--color-background-default);
  border-bottom: 1px solid var(--color-border-default);
  align-items: center;
  height: 32px;
  display: flex;
  position: relative;
}
.bcn-fd-tl__group + .bcn-fd-tl__group .bcn-fd-tl__batch {
  border-top: 1px solid var(--color-border-default);
}
.bcn-fd-tl__batch-text {
  gap: var(--spacing-300);
  padding: 0 var(--spacing-300);
  white-space: nowrap;
  display: inline-flex;
  position: sticky;
  left: 0;
}
.bcn-fd-tl__batch-name {
  font-size: 14px;
  font-weight: var(--typography-font-weight-semibold);
}
.bcn-fd-tl__batch-alert {
  font-weight: var(--typography-font-weight-medium);
  color: var(--color-content-utility-danger);
}
.bcn-fd-tl__cell {
  top: 0;
  bottom: 0;
  left: calc(var(--i) * var(--tl-col));
  width: var(--tl-col);
  z-index: 2;
  justify-content: center;
  align-items: center;
  gap: 2px;
  display: flex;
  position: absolute;
}
.bcn-fd-tl__dot {
  border-radius: var(--radius-full);
  padding: 1px;
  display: inline-flex;
}
.bcn-fd-tl__dot:hover,
.bcn-fd-tl__cell--drill:hover {
  filter: brightness(0.9);
}
.bcn-fd-tl__dot:focus-visible,
.bcn-fd-tl__cell--drill:focus-visible {
  outline: 2px solid var(--color-background-utility-info);
  outline-offset: 1px;
}
.bcn-fd-tl__cell--drill {
  text-decoration: none;
}
.bcn-fd-tl__window {
  height: 2px;
  top: calc(50% - 1px);
  left: calc(var(--from) * var(--tl-col) + var(--tl-col) / 2);
  width: calc((var(--to) - var(--from)) * var(--tl-col));
  background: var(--bcn-gray-500);
  z-index: 1;
  position: absolute;
}
.bcn-fd-tl__bar {
  height: 24px;
  top: calc(50% - 12px);
  left: calc(var(--from) * var(--tl-col));
  width: calc((var(--to) - var(--from) + 1) * var(--tl-col));
  border-radius: var(--radius-100);
  background: var(--color-background-elevation-sunken);
  z-index: 1;
  position: absolute;
}
.bcn-fd-tl__note {
  left: var(--tl-label);
  align-items: center;
  gap: var(--spacing-300);
  height: 100%;
  padding: 0 var(--spacing-300);
  color: var(--color-content-default-tertiary);
  white-space: nowrap;
  display: inline-flex;
  position: sticky;
}
.bcn-fd-tl__note-reason {
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default-secondary);
}
.bcn-fd-tl__foot {
  padding: var(--spacing-200) var(--spacing-400);
  border-top: 1px solid var(--color-border-default);
  background: var(--color-background-default);
  border-radius: 0 0 var(--radius-100) var(--radius-100);
  color: var(--color-content-default-secondary);
}
.bcn-fd-tl__key {
  margin: 0;
  padding: 0;
  list-style: none;
}
.bcn-fd-tl__key-window {
  background: var(--bcn-gray-500);
  width: 24px;
  height: 2px;
  display: inline-block;
}
.bcn-fd-tl__key-today {
  background: var(--color-background-utility-info);
  width: 2px;
  height: 16px;
  display: inline-block;
}
.bcn-fd-tl__count {
  font-variant-numeric: tabular-nums;
}
.cluster {
  --gap: var(--spacing-300, 0.75rem);
  --align: center;
  --justify: flex-start;
  gap: var(--gap);
  align-items: var(--align);
  justify-content: var(--justify);
  flex-wrap: wrap;
  display: flex;
}
.repel {
  --gap: var(--spacing-400, 1rem);
  --align: center;
  gap: var(--gap);
  align-items: var(--align);
  flex-wrap: wrap;
  justify-content: space-between;
  display: flex;
}

.typography-title-strong {
  font-family: var(--typography-title-strong-font-family);
  font-size: var(--typography-title-strong-font-size);
  font-weight: var(--typography-title-strong-font-weight);
  line-height: var(--typography-title-strong-line-height);
  letter-spacing: var(--typography-title-strong-letter-spacing);
}
.bcn-search-trigger .esa-icon {
  color: var(--color-content-default-tertiary);
  flex: none;
}
.bcn-help-bar .esa-icon-button {
  color: var(--bcn-helpbar-fg-muted);
  --icon-button-bg-hover: var(--bcn-helpbar-hover-bg);
}
.bcn-help-bar .esa-icon-button:hover,
.bcn-help-bar .esa-icon-button:focus-visible {
  color: var(--bcn-helpbar-fg);
}
.bcn-gd__label .esa-icon {
  color: var(--color-content-default-tertiary);
  flex: none;
}
.bcn-gd-row .esa-icon {
  color: var(--color-content-default-tertiary);
  flex: none;
}
.bcn-disclosure .esa-icon {
  transition: transform 0.15s;
}
.bcn-disclosure[aria-expanded="false"] .esa-icon {
  transform: rotate(-90deg);
}
.bcn-ev-staging__title .esa-icon {
  color: var(--color-content-default-tertiary);
  flex: none;
}
.bcn-ev-targets__title .esa-icon {
  color: var(--color-content-default-tertiary);
  flex: none;
}
.topbar__right .esa-icon-button {
  color: var(--color-content-default-secondary);
}
.user-panel__item .esa-icon {
  color: var(--bcn-gray-500);
}
.user-panel__item--danger .esa-icon {
  color: var(--color-background-utility-danger);
}
.project-switcher__trigger > .esa-icon:first-child {
  color: var(--bcn-gray-500);
  flex-shrink: 0;
}
.nav-section__header:hover .esa-icon,
.nav-section--active .nav-section__header,
.nav-section--active .nav-section__header .esa-icon {
  color: var(--color-background-brand);
}
.nav-section__header > .esa-icon:first-child {
  color: var(--bcn-gray-950);
  flex-shrink: 0;
  transition: color 0.15s;
}
.nav-section__header > .esa-icon:last-child {
  color: var(--bcn-gray-400);
  flex-shrink: 0;
  transition:
    transform 0.15s,
    opacity 0.2s ease-in-out;
}
.nav-section--collapsed .nav-section__header > .esa-icon:last-child {
  transform: rotate(-90deg);
}
.side-nav.collapsed .nav-section__title,
.side-nav.collapsed .nav-section__header > .esa-icon:last-child {
  display: none;
}
.bcn-fd-mark {
  border-radius: var(--radius-100);
  vertical-align: middle;
  flex-shrink: 0;
  justify-content: center;
  align-items: center;
  width: 28px;
  height: 24px;
  display: inline-flex;
}
.bcn-fd-mark--sm {
  width: 22px;
  height: 20px;
}
.bcn-fd-mark--dot {
  border-radius: var(--radius-full);
  width: 12px;
  height: 12px;
}
.bcn-fd-mark--dot[data-status="missing"] {
  border-radius: 2px;
}
.bcn-fd-mark--bar {
  width: calc(var(--tl-col, 30px) - 2px);
  height: 22px;
  font-size: 12px;
  font-weight: var(--typography-font-weight-semibold);
  border-radius: 3px;
}
.bcn-fd-mark--text {
  width: auto;
  min-width: 3.25rem;
  padding: 0 var(--spacing-200);
  font-size: 13px;
  font-weight: var(--typography-font-weight-semibold);
  font-variant-numeric: tabular-nums;
}
.bcn-fd-mark--bar.bcn-fd-mark--text {
  width: calc(var(--tl-col, 30px) - 2px);
  min-width: 0;
  padding: 0;
  font-size: 12px;
}
.bcn-fd-mark[data-status="received"] {
  background: color-mix(in srgb, var(--bcn-status-completed) 14%, transparent);
  color: var(--bcn-status-completed);
}
.bcn-fd-mark[data-status="late"] {
  background: color-mix(in srgb, var(--bcn-status-in-progress) 26%, transparent);
  color: color-mix(
    in srgb,
    var(--bcn-status-in-progress) 45%,
    var(--color-content-default)
  );
}
.bcn-fd-mark[data-status="missing"] {
  background: var(--bcn-status-overdue);
  color: var(--color-content-on-utility-danger);
}
.bcn-fd-mark[data-status="upcoming"] {
  box-shadow: inset 0 0 0 1px var(--bcn-status-not-started);
  color: var(--color-content-default-tertiary);
}
.bcn-fd-mark--dot[data-status="received"] {
  background: var(--bcn-status-completed);
}
.bcn-fd-mark--dot[data-status="late"] {
  background: var(--bcn-status-in-progress);
}
.bcn-fd-mark--dot[data-status="upcoming"] {
  box-shadow: inset 0 0 0 1.5px var(--bcn-gray-500);
  background: var(--color-background-elevation-raised);
}
.bcn-fd-mark--bar[data-status="upcoming"] {
  background: var(--color-background-elevation-raised);
}
.bcn-fd-checklist {
  --st-fd-received: var(--bcn-status-completed);
  --st-fd-late: var(--bcn-status-in-progress);
  --st-fd-missing: var(--bcn-status-overdue);
  --st-fd-upcoming: var(--bcn-gray-500);
  font-size: 14px;
}
.bcn-fd-checklist__facts {
  gap: var(--spacing-400) var(--spacing-500);
  grid-template-columns: repeat(3, minmax(0, 1fr));
  display: grid;
}
.bcn-fd-checklist__title {
  font-size: 15px;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
  margin: 0;
}
.bcn-fd-checklist__table {
  border-collapse: collapse;
  font-variant-numeric: tabular-nums;
  width: 100%;
}
.bcn-fd-checklist__table th,
.bcn-fd-checklist__table td {
  text-align: left;
  vertical-align: top;
  padding: var(--spacing-200) var(--spacing-300) var(--spacing-200) 0;
  border-bottom: 1px solid var(--color-border-default-subtle);
}
.bcn-fd-checklist__table thead th {
  font-size: 13px;
  font-weight: var(--typography-font-weight-medium);
  color: var(--color-content-default-tertiary);
  border-bottom-color: var(--color-border-default);
}
.bcn-fd-checklist__table tbody th {
  font-weight: var(--typography-font-weight-regular);
}
.bcn-fd-checklist__table td {
  width: 5.5rem;
}
.bcn-fd-checklist__table td:last-child {
  width: 8rem;
  padding-right: 0;
}
.bcn-fd-checklist__table tr[data-status="missing"] > {
  background: color-mix(in srgb, var(--bcn-status-overdue) 6%, transparent);
}
.bcn-fd-checklist__doc,
.bcn-fd-checklist__date,
.bcn-fd-checklist__file,
.bcn-fd-checklist__sub {
  display: block;
}
.bcn-fd-checklist__doc {
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
}
.bcn-fd-checklist__sub {
  color: var(--color-content-default-tertiary);
  font-size: 13px;
}
.bcn-fd-checklist__date {
  white-space: nowrap;
}
.bcn-fd-checklist__file {
  color: var(--color-content-default-secondary);
  overflow-wrap: anywhere;
  margin-top: 2px;
  font-size: 13px;
}
.bcn-fd-checklist__none {
  color: var(--color-content-default-tertiary);
}
.bcn-fd-days__head,
.bcn-fd-days__summary {
  align-items: center;
  column-gap: var(--spacing-300);
  grid-template-columns: 1fr repeat(3, 7.5rem);
  display: grid;
}
.bcn-fd-days__head {
  font-size: 13px;
  font-weight: var(--typography-font-weight-medium);
  color: var(--color-content-default-tertiary);
  padding-bottom: var(--spacing-200);
  border-bottom: 1px solid var(--color-border-default);
}
.bcn-fd-days__head span:not(:first-child) {
  text-align: center;
}
.bcn-fd-days__day {
  border-bottom: 1px solid var(--color-border-default-subtle);
}
.bcn-fd-days__summary {
  cursor: pointer;
  padding: var(--spacing-200) 0;
  list-style: none;
}
.bcn-fd-days__summary::-webkit-details-marker {
  display: none;
}
.bcn-fd-days__date {
  align-items: center;
  gap: var(--spacing-100);
  font-weight: var(--typography-font-weight-semibold);
  display: inline-flex;
}
.bcn-fd-days__date svg {
  color: var(--color-content-default-tertiary);
  transition: transform 0.12s;
}
.bcn-fd-days__day[open] .bcn-fd-days__date svg {
  transform: rotate(90deg);
}
.bcn-fd-days__mark {
  justify-self: center;
  display: inline-flex;
}
.bcn-fd-checklist__table tr[data-fd-target] >,
.bcn-fd-days__day[data-fd-target] {
  background: color-mix(in srgb, var(--color-background-utility-info) 9%, transparent);
}
.bcn-fd-days__records {
  margin: 0 0 var(--spacing-200) var(--spacing-500);
  width: calc(100% - var(--spacing-500));
}
.bcn-fd-days__records tr:last-child > {
  border-bottom: 0;
}
.typography-title-strong {
  font-family: var(--typography-title-strong-font-family);
  font-size: var(--typography-title-strong-font-size);
  font-weight: var(--typography-title-strong-font-weight);
  line-height: var(--typography-title-strong-line-height);
  letter-spacing: var(--typography-title-strong-letter-spacing);
}
.bcn-key-value {
  flex-direction: column;
  gap: 2px;
  display: flex;
}
.bcn-key-value[data-layout="row"] {
  align-items: baseline;
  column-gap: var(--spacing-300);
  grid-template-columns: 6.5rem minmax(0, 1fr);
  display: grid;
}
.bcn-key-value__key {
  font-size: var(--typography-label-md-font-size);
  font-weight: var(--typography-font-weight-medium);
  color: var(--form-label-color);
}
.bcn-key-value__val {
  font-size: var(--typography-label-md-font-size);
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
}
.bcn-key-value__hint {
  color: var(--color-content-default-tertiary);
  font-size: 0.75rem;
}
.bcn-key-value__key {
  align-items: center;
  gap: var(--spacing-100);
  display: inline-flex;
}
.bcn-key-value__key .esa-icon {
  color: var(--color-content-default-tertiary);
}
.bcn-key-value[data-size="sm"] .bcn-key-value__key {
  font-size: var(--typography-label-sm-font-size);
  font-weight: var(--typography-label-sm-font-weight);
  color: var(--color-content-secondary);
}
.bcn-key-value[data-size="sm"] .bcn-key-value__val {
  font-size: var(--typography-label-sm-strong-font-size);
  font-weight: var(--typography-label-sm-strong-font-weight);
}
.bcn-status-chip {
  align-items: center;
  gap: var(--spacing-150);
  padding: 2px var(--spacing-250);
  border-radius: var(--radius-full);
  font-size: var(--font-size-100);
  font-weight: var(--typography-font-weight-semibold);
  white-space: nowrap;
  background: color-mix(in srgb, var(--_chip) 16%, transparent);
  color: color-mix(in srgb, var(--_chip) 72%, #1a1a1a);
  display: inline-flex;
}
.bcn-status-chip__dot {
  border-radius: var(--radius-full);
  background: var(--_chip);
  flex-shrink: 0;
  width: 8px;
  height: 8px;
}
.esa-icon {
  --_icon-size: var(--icon-size-md, 20px);
  width: var(--_icon-size);
  height: var(--_icon-size);
  color: inherit;
  justify-content: center;
  align-items: center;
  display: inline-flex;
}
.esa-icon--xs {
  --_icon-size: var(--icon-size-xs, 14px);
}
.esa-icon--sm {
  --_icon-size: var(--icon-size-sm, 16px);
}
.esa-icon--md {
  --_icon-size: var(--icon-size-md, 20px);
}
.esa-icon--lg {
  --_icon-size: var(--icon-size-lg, 24px);
}
.esa-icon--xl {
  --_icon-size: var(--icon-size-xl, 28px);
}
.esa-icon svg {
  width: var(--_icon-size);
  height: var(--_icon-size);
  display: block;
}
.breadcrumbs__items .esa-icon {
  color: var(--bcn-gray-400);
}
.page-layout__title h1 .esa-icon {
  color: var(--page-title-icon-color, var(--bcn-gray-1000));
  flex-shrink: 0;
}
.stack {
  --gap: var(--spacing-400, 1rem);
  gap: var(--gap);
  flex-direction: column;
  display: flex;
}
.stack[data-split] > [data-split] {
  margin-block-end: auto;
}
.cluster {
  --gap: var(--spacing-300, 0.75rem);
  --align: center;
  --justify: flex-start;
  gap: var(--gap);
  align-items: var(--align);
  justify-content: var(--justify);
  flex-wrap: wrap;
  display: flex;
}
